-- Jeu de LecteurNaturesDocument / EcrivainNaturesDocument (« Natures de document », PROC_GED_NATURE_DOC), lot 14 du plan-676a4b19.
-- Identifiants 24003xx, codes « L14... ». Les tables aux types de RIG_DEV (VIDIGED_PARAMETRAGE.cs, VIDIGED_INDEX.cs et
-- WEBS_DOC_REGROUPEMENT.cs de RigBaseGreffe). Ce jeu est joue AVANT ceux qui creent VIDIGED_INDEX (PROC_ORDOSIGN, PROC_SDEMATJUD) et
-- VIDIGED_PARAMETRAGE (PROC_SDEMATJUD) : VIDIGED_INDEX recoit la definition exacte de PROC_ORDOSIGN.sql, VIDIGED_PARAMETRAGE celle de
-- PROC_SDEMATJUD.sql, plus les colonnes que la fiche lit (nullables : les INSERT des autres jeux nomment leurs colonnes).
IF OBJECT_ID(N'v2.VIDIGED_PARAMETRAGE') IS NULL
    CREATE TABLE v2.VIDIGED_PARAMETRAGE (VGPRM_ID_VGPRM int NOT NULL PRIMARY KEY, VGPRM_TYPE varchar(50) NULL, VGPRM_CODE varchar(50) NULL,
        VGPRM_LIBELLE varchar(1000) NULL);
IF COL_LENGTH('v2.VIDIGED_PARAMETRAGE', 'VGPRM_EXPERIAN') IS NULL ALTER TABLE v2.VIDIGED_PARAMETRAGE ADD VGPRM_EXPERIAN varchar(50) NULL;
IF COL_LENGTH('v2.VIDIGED_PARAMETRAGE', 'VGPRM_EXPERIAN_GEIDE') IS NULL ALTER TABLE v2.VIDIGED_PARAMETRAGE ADD VGPRM_EXPERIAN_GEIDE varchar(50) NULL;
IF COL_LENGTH('v2.VIDIGED_PARAMETRAGE', 'VGPRM_EXPERIAN_COFFRE') IS NULL ALTER TABLE v2.VIDIGED_PARAMETRAGE ADD VGPRM_EXPERIAN_COFFRE varchar(50) NULL;
IF COL_LENGTH('v2.VIDIGED_PARAMETRAGE', 'VGPRM_COPIE_CONFORME_CENTRALISATION') IS NULL ALTER TABLE v2.VIDIGED_PARAMETRAGE ADD VGPRM_COPIE_CONFORME_CENTRALISATION varchar(50) NULL;
IF COL_LENGTH('v2.VIDIGED_PARAMETRAGE', 'VGPRM_PARAMETRE_EDITION_CFEC') IS NULL ALTER TABLE v2.VIDIGED_PARAMETRAGE ADD VGPRM_PARAMETRE_EDITION_CFEC varchar(20) NULL;
IF COL_LENGTH('v2.VIDIGED_PARAMETRAGE', 'VGPRM_WEBS_DOC_REGROUPEMENT') IS NULL ALTER TABLE v2.VIDIGED_PARAMETRAGE ADD VGPRM_WEBS_DOC_REGROUPEMENT varchar(3) NULL;
IF COL_LENGTH('v2.VIDIGED_PARAMETRAGE', 'VGPRM_EXPERIAN_TRCNC_EP_D') IS NULL ALTER TABLE v2.VIDIGED_PARAMETRAGE ADD VGPRM_EXPERIAN_TRCNC_EP_D varchar(10) NULL;
IF COL_LENGTH('v2.VIDIGED_PARAMETRAGE', 'VGPRM_EXPERIAN_TRCNC_EP_F') IS NULL ALTER TABLE v2.VIDIGED_PARAMETRAGE ADD VGPRM_EXPERIAN_TRCNC_EP_F varchar(10) NULL;
IF COL_LENGTH('v2.VIDIGED_PARAMETRAGE', 'VGPRM_TRIBUNAL_DIGITAL_NATURE_DOC') IS NULL ALTER TABLE v2.VIDIGED_PARAMETRAGE ADD VGPRM_TRIBUNAL_DIGITAL_NATURE_DOC varchar(50) NULL;
IF OBJECT_ID(N'v2.VIDIGED_INDEX') IS NULL
    CREATE TABLE v2.VIDIGED_INDEX (VGIDX_ID_VGIDX int NOT NULL PRIMARY KEY, VGIDX_ID_ENTITE int NULL, VGIDX_TYPE_ENTITE varchar(50) NULL,
        VGIDX_ID_DCJDC int NULL, VGIDX_ID_PBLCT int NULL, VGIDX_NATURE_DOC varchar(50) NULL, VGIDX_DATE_RECEPTION datetime NULL);
IF COL_LENGTH('v2.VIDIGED_INDEX', 'VGIDX_NATURE_DOC') IS NULL ALTER TABLE v2.VIDIGED_INDEX ADD VGIDX_NATURE_DOC varchar(50) NULL;
IF OBJECT_ID(N'v2.WEBS_DOC_REGROUPEMENT') IS NULL
    CREATE TABLE v2.WEBS_DOC_REGROUPEMENT (R_WEBSDOCREG_VALEUR varchar(3) NOT NULL PRIMARY KEY, R_WEBSDOCREG_LIBELLE_ECRAN varchar(40) NOT NULL,
        R_WEBSDOCREG_NUM_ORDRE int NOT NULL);

EXEC sp_executesql N'
INSERT INTO v2.WEBS_DOC_REGROUPEMENT (R_WEBSDOCREG_VALEUR, R_WEBSDOCREG_LIBELLE_ECRAN, R_WEBSDOCREG_NUM_ORDRE) VALUES
    (''L1'', ''Regroupement banc'', 1), (''L2'', ''Regroupement deux'', 2);
